def step1_records(trace):
    """Kept evidence of a completed Step 1 run (unlinked statements included), as Step 3 records grouped by article, with every thesis
    question and, per article, the thesis ids it opened. `trace` may join continuation segments with '+'. An article is numbered by its
    position in the first segment's manifest, so a failed item never shifts the numbers of the articles after it. A record keeps Step 1's
    verified passages beside the model's (None marks a passage not found in the source). A link resolves as the runner resolves it,
    by its type: an existing target must be among the theses shown open, a new one among the theses the answer opened; any other link
    stays out of `thesis_ids` and is listed in `unresolved_thesis_ids` as '<type>:<id>'."""
    questions = {}
    articles = []
    opened = []
    rows = []
    position = None
    for part in trace.split('+'):
        conn = sqlite3.connect(f'file:{part}?mode=ro', uri=True)
        try:
            if position is None:
                position = {iid: n for n, iid in enumerate(json.loads(conn.execute('select manifest from run').fetchone()[0])['item_ids'], 1)}
            done = conn.execute("select input_id, request, result, before_state, after_state from trace where status='complete' order by sequence").fetchall()
        finally:
            conn.close()
        rows += [(position[row[0]], *row[1:]) for row in done]
    for seq, request, result, before, after in rows:
        source = json.JSONDecoder().raw_decode(json.loads(request)['messages'][1]['content'])[0]['source_item']
        questions.update({t['id']: t['description'] for t in json.loads(after)})
        opened.append(sorted({t['id'] for t in json.loads(after)} - {t['id'] for t in json.loads(before)}))
        answer = json.loads(result)
        local = answer.get('new_thesis_ids', {})
        open_before = {t['id'] for t in json.loads(before)}
        def resolve(link):   # the runner's own rule: an existing target must have been shown open; a new one must have been opened
            if link['target_type'] == 'existing':
                return link['target_id'] if link['target_id'] in open_before else None
            return local.get(link['target_id'])
        def targets(ev, resolved):
            if resolved:
                return sorted({resolve(l) for l in ev['links'] if resolve(l)})
            return sorted({f"{l['target_type']}:{l['target_id']}" for l in ev['links'] if not resolve(l)})
        articles.append([{'id': f"{seq}:{ev['local_id']}", 'article': seq, 'input_id': source['id'], 'title': source.get('title'),
                          'publisher': source['publisher'], 'publication_date': source['publication_date'], 'summary': ev['summary'],
                          'passages': ev['source_passages'], 'verified_passages': ev.get('verified_source_passages'),
                          'original_party': ev['original_party'],
                          'reporting_speaker': ev['reporting_speaker'], 'tier': ev['tier'], 'statement_date': ev['statement_date'],
                          'statement_date_text': ev['statement_date_text'], 'evidence_period': ev['evidence_period'],
                          'figures': ev.get('figures') or [],
                          'thesis_ids': targets(ev, True), 'unresolved_thesis_ids': targets(ev, False)}
                         for ev in answer['evidence']])
    kept = [i for i, a in enumerate(articles) if a]
    return [articles[i] for i in kept], questions, [opened[i] for i in kept]


    def reserve(self, amount):
        with self._locked() as state:
            granted = not (state.get('stopped') or state['overrun'] or state['spent'] + state['reserved'] + amount > state['ceiling'])
            if granted:
                state['reserved'] += amount
                state['attempts'] += 1
            else:
                state['refused'] += 1
                if not state.get('stopped'):
                    state['stopped'] = True
                    state['stop_reason'] = 'overrun' if state['overrun'] else f'a reservation of ${amount:.6f} would pass the ${state["ceiling"]:.2f} ceiling'
        if not granted:
            self._note({'refused': amount})                  # after the stop is saved
            return False
        _LIVE.depth = getattr(_LIVE, 'depth', 0) + 1
        return True

    @staticmethod
    def estimate(request):
        """The shared reservation of one language-model attempt (WIRING-DESIGN.md §B): `llm_estimate`."""
        return llm_estimate(request)

    def settle(self, reserved, actual, kind='llm', tokens=None):
        """Settle one attempt. A missing, non-finite, zero or negative charge settles at the whole reservation: an answered paid
        request never costs nothing, and a failed attempt is charged its reservation. `kind` (llm, jev, embeddings) and the reported
        `tokens` go to the attempt line only."""
        _LIVE.depth = max(0, getattr(_LIVE, 'depth', 0) - 1)
        if not isinstance(actual, (int, float)) or isinstance(actual, bool) or not math.isfinite(actual) or actual <= 0:
            actual = reserved
        with self._locked() as state:
            state['reserved'] = max(0.0, state['reserved'] - reserved)
            state['spent'] += actual
            if actual > reserved + 1e-12:
                state['overrun'] = True
                if not state.get('stopped'):
                    state['stopped'], state['stop_reason'] = True, 'overrun'
        self._note({'kind': kind, 'reserved': reserved, 'charged': actual, **({'tokens': tokens} if tokens is not None else {})})

    def stop_if_a_launcher_is_gone(self):
        """Under the ledger's lock: a registered launcher whose lock no process holds died without removing its entry; the ledger is
        stopped. A relaunch calls this before it takes its own lock, so its new lock never makes a stale entry look alive; the stop gate
        calls it before every send. Returns the state after the check."""
        with self._locked() as state:
            if not state.get('stopped'):
                for label, lock_path in sorted((state.get('launchers') or {}).items()):
                    if lock_is_free(lock_path):
                        state['stopped'], state['stop_reason'] = True, f'the launcher of {label} is gone'
                        break
            return dict(state)

    def claim_launcher(self, label, lock_handle):
        """One step under the ledger's lock (council mo, D449): stop the ledger if any registered launcher's lock is free; try the
        launcher's own lock without blocking (False: another launch of this label is running); if this label is still registered once
        its lock is held, the previous launcher died without removing its entry, so the ledger stops; then register. The stop gate's
        probe takes the same lock, so no send can see a stale entry as alive while a new launcher takes its lock."""
        with self._locked() as state:
            launchers = state.setdefault('launchers', {})
            if not state.get('stopped'):
                for other, lock_path in sorted(launchers.items()):
                    if lock_is_free(lock_path):
                        state['stopped'], state['stop_reason'] = True, f'the launcher of {other} is gone'
                        break
            try:
                fcntl.flock(lock_handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                return False
            if label in launchers and not state.get('stopped'):
                state['stopped'], state['stop_reason'] = True, f'the launcher of {label} is gone'
            launchers[label] = os.path.abspath(lock_handle.name)
            return True

    def register_launcher(self, label, lock_path):
        """Register a launcher's lock path (tests and proofs; a launcher uses `claim_launcher`)."""
        with self._locked() as state:
            state.setdefault('launchers', {})[label] = str(lock_path)

    def remove_launcher(self, label):
        """Called by a launcher on a normal end, before it releases its lock."""
        with self._locked() as state:
            (state.get('launchers') or {}).pop(label, None)

    def stop(self, reason):
        """A stop any component records: every later reservation is refused."""
        with self._locked() as state:
            if not state.get('stopped'):
                state['stopped'], state['stop_reason'] = True, reason

    def read(self):
        with open(self.lock_path, 'a+') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX)
            try:
                return json.loads(self.path.read_text())
            finally:
                fcntl.flock(lock, fcntl.LOCK_UN)
